#include "lol_game_report_web_assets.hpp"

namespace sources::lol_game_report::web_assets {
const QByteArray &html()
{
	static const QByteArray value =
		R"(<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>League Game Report</title><link rel="stylesheet" href="/assets/recap.css"><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script></head><body><main id="app"><p class="loading">Loading local report…</p></main><script src="/assets/recap.js"></script></body></html>)";
	return value;
}

const QByteArray &css()
{
	static const QByteArray value =
		R"( :root{color-scheme:dark;--bg:#0e1420;--panel:#171f2e;--line:#2b3850;--text:#edf3ff;--muted:#9caec9;--blue:#86c5ff;--gold:#e8bb5a;--win:#61d59b;--loss:#f07886}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px Inter,ui-sans-serif,system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:32px}.loading{color:var(--muted)}h1,h2,h3,p{margin:0}h1{font-size:clamp(28px,4vw,52px);color:var(--blue)}h2{font-size:22px;margin-bottom:18px}h3{font-size:16px;color:var(--muted)}.hero,.section{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:24px;margin-bottom:20px}.sub,.muted{color:var(--muted);margin-top:8px}.outcome{font-weight:800;color:var(--win)}.outcome.Defeat{color:var(--loss)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-top:22px}.metric{padding:14px;background:#101827;border-radius:10px}.metric strong{display:block;font-size:22px;margin-top:4px}.split{display:grid;grid-template-columns:minmax(260px,1fr) 2fr;gap:20px}.chart{min-height:380px}.controls{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-bottom:12px}.controls label{font-size:14px;color:var(--muted)}button,select{background:#24324a;color:var(--text);border:1px solid #3b4b67;border-radius:7px;padding:7px 10px}button.active{background:#3779b8;border-color:var(--blue)}.heatmap{height:330px;position:relative;background:radial-gradient(circle at 50% 50%,#172a42,#101827);border-radius:10px;overflow:hidden}.dot{position:absolute;border-radius:50%;background:#51d6ff;transform:translate(-50%,-50%);mix-blend-mode:screen}.timeline{position:relative;height:88px;border-top:1px solid var(--line);margin-top:12px}.event{position:absolute;top:10px;width:12px;height:12px;border-radius:50%;background:var(--gold)}.event.kill{background:#f07886}.event.tower{background:#af8cf5}.event.level{background:#61d59b}.event.item{background:#86c5ff}.event span{display:none;position:absolute;top:16px;left:-45px;width:110px;background:#101827;border:1px solid var(--line);padding:6px;border-radius:5px;font-size:12px;z-index:2}.event:hover span{display:block}.build,.abilities{display:flex;gap:12px;flex-wrap:wrap}.build-item,.ability{min-width:76px;text-align:center;color:var(--muted);font-size:13px}.build-item img,.champion{width:48px;height:48px;border-radius:8px;object-fit:cover;background:#101827}.ability b{display:block;color:var(--text);font-size:20px}.insight{border-left:3px solid var(--blue);padding:8px 12px;margin:10px 0;background:#111a29}.notice{color:var(--muted);font-size:13px}.footer{color:var(--muted);font-size:12px;padding:16px 0}@media(max-width:760px){main{padding:16px}.split{grid-template-columns:1fr}.hero,.section{padding:18px}})";
	return value;
}

const QByteArray &script()
{
	static const QByteArray value =
		R"(const $=s=>document.querySelector(s), fmt=s=>`${Math.floor(s/60)}:${String(Math.round(s%60)).padStart(2,'0')}`, n=v=>Number(v||0).toLocaleString(), avg=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:0;
const query=new URLSearchParams(location.search), id=query.get('report'), url=id?'/api/report/'+encodeURIComponent(id):'/api/latest';
const icon=(kind,version,value)=>version&&value?`<img loading="lazy" src="/assets/ddragon/${kind}/${encodeURIComponent(version)}/${encodeURIComponent(value)}" onerror="this.style.visibility='hidden'">`:'';
const abilityIcon=(version,champion,slot)=>version&&champion?`<img loading="lazy" src="/assets/ddragon/ability/${encodeURIComponent(version)}/${encodeURIComponent(champion)}/${slot}" onerror="this.style.visibility='hidden'">`:'';
function metric(label,value){return `<div class="metric"><h3>${label}</h3><strong>${value}</strong></div>`}
function series(r,key){if(key==='apm'){return r.input_samples.map(s=>({x:s.seconds,y:s.actions*60}));}if(key==='velocity'){return r.input_samples.map(s=>({x:s.seconds,y:s.max_velocity_pixels_per_second}));}return r.samples.map(s=>({x:s.seconds,y:key==='gold'?s.estimated_gold:s[key]}));}
function normalized(points,mode){const values=points.map(p=>p.y), lo=Math.min(...values),hi=Math.max(...values),mean=avg(values);return points.map(p=>({x:p.x,y:mode==='average'?p.y/(mean||1):(p.y-lo)/((hi-lo)||1)}));}
function render(r){const final=r.samples.at(-1)||{}, input=r.input_samples||[], actions=input.reduce((x,s)=>x+s.actions,0),dist=input.reduce((x,s)=>x+s.mouse_distance_pixels,0),vel=input.map(s=>s.max_velocity_pixels_per_second),minutes=(r.duration_seconds||1)/60, version=r.assets?.ddragon_version||''; const champion=icon('champion',version,r.champion);$('#app').innerHTML=`<section class="hero"><div class="split"><div><h1>${champion} ${r.champion||'League Game Report'}</h1><p class="sub">${r.completed_at?.slice(0,16).replace('T',' ')} · ${r.game_mode||'Unavailable'} · ${r.map||''}</p><p class="outcome ${r.outcome}">${r.outcome||'Outcome unavailable'} · ${fmt(r.duration_seconds||0)}</p></div><div class="grid">${metric('Team gold',r.team_gold?`${n(r.team_gold)} / ${n(r.enemy_team_gold)}`:'Unavailable')}${metric('Team kills',r.team_kills?`${n(r.team_kills)} / ${n(r.enemy_team_kills)}`:'Unavailable')}${metric('Riot ID',r.player||'Unavailable')}${metric('Game ID',r.game_id||'Unavailable')}</div></div><div class="grid">${metric('K / D / A',`${final.kills||0} / ${final.deaths||0} / ${final.assists||0}`)}${metric('CS / CSPM',`${n(final.cs)} / ${(final.cs/minutes).toFixed(1)}`)}${metric('Gold / GPM',`${n(final.estimated_gold)} / ${(final.estimated_gold/minutes).toFixed(0)}`)}${metric('Role',r.role||'Unavailable')}</div></section><section class="section"><h2>Performance data</h2><div class="split"><div><div class="heatmap" id="heatmap"></div><p class="notice">Mouse movement and distance are display-coordinate estimates; DPI snapshot: ${n(r.dpi||800)}.</p></div><div class="grid">${metric('Total actions',n(actions))}${metric('Mouse distance',`${n(Math.round(dist))} px`)}${metric('Max / avg APM',`${n(Math.max(...input.map(s=>s.actions*60),0))} / ${n(Math.round(avg(input.map(s=>s.actions*60))))}`)}${metric('Max / avg velocity',`${n(Math.round(Math.max(...vel,0)))} / ${n(Math.round(avg(vel)))} px/s`)}</div></div></section><section class="section"><h2>Game data</h2><div class="controls"><label>Normalization <select id="norm"><option value="minmax">Min–max</option><option value="average">Game average ratio</option></select></label>${['apm','velocity','cs','gold','level'].map(x=>`<button data-series="${x}" class="active">${x==='gold'?'estimated gold':x==='level'?'level progression':x}</button>`).join('')}</div><div class="chart"><canvas id="chart"></canvas></div><h3>Game events</h3><div class="controls">${['kill','objective','tower','level','item'].map(x=>`<button data-event="${x}" class="active">${x}</button>`).join('')}</div><div class="timeline" id="events"></div><p class="notice">Level progression is stepped because the local game API does not provide fractional XP history. Estimated gold represents earned gold when available.</p></section><section class="section"><h2>Ability leveling path</h2><div class="abilities">${(r.abilities||[]).map(a=>`<div class="ability">${abilityIcon(version,r.champion,a.ability)}<b>${a.ability}${a.level}</b>${fmt(a.seconds)}</div>`).join('')||'<p class="muted">Unavailable for this report.</p>'}</div><h2 style="margin-top:28px">Player build</h2><div class="build">${(r.item_events||[]).map(i=>`<div class="build-item">${icon('item',version,i.item_id)}<div>${i.item||`Item ${i.item_id}`}</div><small>${fmt(i.seconds)}</small></div>`).join('')||'<p class="muted">Unavailable for this report.</p>'}</div></section><section class="section"><h2>Timeseries insights</h2><div id="insights"></div></section><footer class="footer">Self-only local data. Riot Games is not endorsing or sponsoring this source.</footer>`;
 for(const b of r.heatmap||[]){const d=document.createElement('i');d.className='dot';d.style.left=`${(b.x+0.5)/30*100}%`;d.style.top=`${(b.y+0.5)/17*100}%`;d.style.width=d.style.height=`${Math.min(70,8+Math.sqrt(b.count)*5)}px`;d.style.opacity=Math.min(1,.18+b.count/100);$('#heatmap').append(d)};
 const insights=[];const first=(r.item_events||[])[0];if(first)insights.push(`First build event: <b>${first.item||'Item '+first.item_id}</b> at ${fmt(first.seconds)}.`);for(const a of r.abilities||[])if([6,11,16].includes(a.level))insights.push(`Level ${a.level} milestone at ${fmt(a.seconds)}.`);if(!insights.length)insights.push('More insights will appear as local game samples are collected.');$('#insights').innerHTML=insights.map(x=>`<div class="insight">${x}</div>`).join('');
 let chart; const update=()=>{const keys=[...document.querySelectorAll('[data-series].active')].map(x=>x.dataset.series),mode=$('#norm').value;if(!window.Chart){$('.chart').innerHTML='<p class="notice">Charts need the configured Chart.js CDN connection. Metrics and event data remain available.</p>';return}chart?.destroy();chart=new Chart($('#chart'),{type:'line',data:{datasets:keys.map((k,i)=>({label:k==='gold'?'estimated gold':k,data:normalized(series(r,k),mode),borderColor:['#86c5ff','#e8bb5a','#61d59b','#f07886','#af8cf5'][i],pointRadius:0,tension:.25}))},options:{responsive:true,maintainAspectRatio:false,parsing:false,scales:{x:{type:'linear',title:{display:true,text:'Game time (seconds)'}},y:{title:{display:true,text:mode==='average'?'ratio to game average':'normalized value'}}},plugins:{tooltip:{callbacks:{title:x=>fmt(x[0].parsed.x)}}}}})};document.querySelectorAll('[data-series]').forEach(b=>b.onclick=()=>{b.classList.toggle('active');update()});$('#norm').onchange=update;update();
 const drawEvents=()=>{const enabled=new Set([...document.querySelectorAll('[data-event].active')].map(x=>x.dataset.event));$('#events').innerHTML=(r.events||[]).filter(e=>enabled.has(e.category)).map(e=>`<i class="event ${e.category}" style="left:${Math.min(100,e.seconds/(r.duration_seconds||1)*100)}%"><span>${fmt(e.seconds)} · ${e.detail||e.type}</span></i>`).join('')};document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{b.classList.toggle('active');drawEvents()});drawEvents();}
fetch(url).then(x=>x.ok?x.json():Promise.reject()).then(render).catch(()=>$('#app').innerHTML='<section class="hero"><h1>Report unavailable</h1><p class="sub">This report is no longer stored by the local plugin.</p></section>');)";
	return value;
}
} // namespace sources::lol_game_report::web_assets
